def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = {}
    for aid, opp in opponents_status.items():
        if opp.get('alive'):
            alive[aid] = opp

    if not alive:
        return min(budget, 18.0)

    severe_need = hp <= 3 or no_water_days >= 2
    moderate_need = hp <= 5 or no_water_days >= 1

    total_agents = 1 + len(alive)
    expected_share = float(supply) / float(total_agents)
    scarce = expected_share < WATER_REQ
    very_scarce = supply <= 17
    abundant = supply >= 22

    highest_prev = 0.0
    cindy_prev = None
    pressure_count = 0
    desperate_opp = 0

    for aid, opp in alive.items():
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            if bid > highest_prev:
                highest_prev = bid
            if bid >= 90:
                pressure_count += 1
            if aid == 'Cindy':
                cindy_prev = bid
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            desperate_opp += 1

    if cindy_prev is None:
        cindy_prev = 0.0

    if severe_need:
        target = max(78.0, cindy_prev + 3.0, highest_prev * 0.72)
        if very_scarce:
            target = max(target, 92.0)
        return float(min(budget, target))

    if abundant and not moderate_need:
        low = 8.0
        if cindy_prev >= 120:
            low = 5.0
        elif highest_prev < 40:
            low = 16.0
        return float(min(budget, low))

    if scarce:
        if cindy_prev >= 130:
            target = 54.0 if not moderate_need else 84.0
        elif cindy_prev >= 110:
            target = 60.0 if not moderate_need else 88.0
        elif cindy_prev >= 80:
            target = cindy_prev + 2.0 if moderate_need else cindy_prev - 10.0
        else:
            target = 58.0 if not moderate_need else 82.0

        if desperate_opp >= 2:
            target += 8.0
        if very_scarce:
            target += 10.0
        return float(min(budget, target))

    target = 28.0
    if moderate_need:
        target = 52.0
    if pressure_count >= 2:
        target += 8.0
    if highest_prev >= 100 and not moderate_need:
        target = 22.0

    if day >= 8 and hp >= 6 and no_water_days == 0:
        target = min(target, 20.0)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from opponents' previous_trace (immediate reaction only)
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Estimate how many water units are likely available
    # (Only used to scale bid; indices not needed.)
    expected_units = supply / WATER_REQ

    # Determine urgency: if I've already gone without water, increase pressure.
    urgency_factor = 1.0
    if no_water_days >= 2:
        urgency_factor = 1.25
    if hp <= 2:
        urgency_factor = 1.6
    elif hp <= 4:
        urgency_factor = 1.3

    # Cindy-like pattern: if someone previously bid very high and survived, she likely continues.
    # We avoid matching the absolute max; instead we target just above the likely low-mid bids.
    target_base = DAILY_SALARY * 0.55

    # If highest previous bid was extremely high, treat it as a ceiling threat.
    # Bid slightly above the second-highest to steal water from everyone except the top spender.
    if highest_prev_bid >= DAILY_SALARY * 1.35:
        target_base = max(target_base, second_prev_bid + 2.0)
        # Still cap below the top bidder to avoid unnecessary budget burn.
        cap = min(DAILY_SALARY * 1.05, highest_prev_bid - 5.0)
        target = min(cap, target_base)
    else:
        # Otherwise, bid around the cluster midpoint or just above highest_prev_bid.
        if highest_prev_bid > 0:
            target = max(target_base, min(highest_prev_bid + 1.5, DAILY_SALARY * 0.95))
        else:
            target = target_base

    # Scale with expected scarcity: lower supply => more competitive => bid a bit more.
    scarcity_factor = 1.0
    if supply <= 17.0:
        scarcity_factor = 1.15
    elif supply <= 19.0:
        scarcity_factor = 1.08
    elif supply >= 22.0:
        scarcity_factor = 0.95

    bid = target * urgency_factor * scarcity_factor

    # Budget safety: never exceed budget; also avoid bidding too low when hp is critical.
    bid = max(0.0, min(budget, bid))

    # Hard floor when hp is low to prevent immediate death.
    if hp <= 2.5 and budget > 0:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    # If budget is tiny, bid proportionally.
    if budget < DAILY_SALARY * 0.4:
        bid = min(budget, bid)

    return float(bid)
